"""Minimal Linear GraphQL client.

Reads ``LINEAR_API_KEY`` from the environment. The CLI entrypoint
(``cli.main``) loads ``.env`` from the drain-cycle repo root before this
module is exercised; a shell-exported value still takes precedence.
Single-team scope: hardcoded to the ``Personal`` team per README §1.
"""
from __future__ import annotations

import os
from dataclasses import dataclass
from typing import Any

import httpx

from . import telemetry

_DEFAULT_GRAPHQL_URL = "https://api.linear.app/graphql"
_TEAM_NAME = "Personal"
_PENDING_STATE_TYPES = ["backlog", "unstarted"]
_RESOLVED_STATE_TYPES = {"completed", "canceled"}


@dataclass(frozen=True)
class ExecutionPlan:
    """Result of ``_plan``: runnable issues in topo order + deferred issues."""
    order: list[dict[str, Any]]   # issues to spawn, in execution order
    deferred: list[dict[str, Any]]  # each {"issue", "blocker_identifier", "blocker_state_type"}


class DependencyCycleError(RuntimeError):
    """Raised when the blocks graph among pending issues contains a cycle."""
    def __init__(self, identifiers: list[str]) -> None:
        self.identifiers = list(identifiers)
        super().__init__(f"Dependency cycle among: {', '.join(identifiers)}")


def _post(
    query: str,
    variables: dict[str, Any] | None = None,
    *,
    operation: str = "graphql",
) -> dict[str, Any]:
    """Execute one GraphQL request. ``operation`` names the span and the
    ``linear.operation`` attribute so the five distinct calls (which all POST
    to the same endpoint) stay separable in Honeycomb; the httpx transport is
    auto-instrumented, so the raw HTTP POST appears as a child span."""
    with telemetry.tracer.start_as_current_span(f"linear.{operation}") as span:
        span.set_attribute("linear.operation", operation)
        key = os.environ.get("LINEAR_API_KEY")
        if not key:
            telemetry.mark_error(span, "err-linear-no-api-key", "LINEAR_API_KEY is not set")
            raise RuntimeError("LINEAR_API_KEY is not set")
        url = os.environ.get("LINEAR_API_URL", _DEFAULT_GRAPHQL_URL)
        resp = httpx.post(
            url,
            headers={"Authorization": key, "Content-Type": "application/json"},
            json={"query": query, "variables": variables or {}},
            timeout=30.0,
        )
        try:
            resp.raise_for_status()
        except httpx.HTTPStatusError as exc:
            span.set_attribute("http.response.status_code", resp.status_code)
            telemetry.mark_error(span, "err-linear-http", str(exc))
            raise
        body = resp.json()
        if "errors" in body:
            telemetry.mark_error(span, "err-linear-graphql", "Linear GraphQL errors")
            raise RuntimeError(f"Linear GraphQL errors: {body['errors']}")
        return body["data"]


def current_cycle_id() -> str:
    """Return the active cycle id for the configured team."""
    data = _post(
        """
        query CurrentCycle($name: String!) {
          teams(filter: { name: { eq: $name } }) {
            nodes {
              id
              activeCycle { id }
            }
          }
        }
        """,
        {"name": _TEAM_NAME},
        operation="current_cycle",
    )
    nodes = data["teams"]["nodes"]
    if not nodes:
        raise RuntimeError(f"Linear team {_TEAM_NAME!r} not found")
    cycle = nodes[0].get("activeCycle")
    if not cycle:
        raise RuntimeError(f"Linear team {_TEAM_NAME!r} has no active cycle")
    return cycle["id"]


def _plan(issues: list[dict[str, Any]]) -> ExecutionPlan:
    """Topological sort over ``issues`` respecting blocks/blocked-by.

    Returns an ``ExecutionPlan`` with ``order`` (runnable, topo-sorted by
    ``(sortOrder, id)`` tiebreak) and ``deferred`` (issues skipped because
    an external unresolved blocker exists, or because a blocking issue in
    the drain was itself deferred — cascade).

    Raises ``DependencyCycleError`` when the intra-set blocks graph contains
    a cycle (self-loops included).
    """
    P: set[str] = {i["id"] for i in issues}
    by_id: dict[str, dict[str, Any]] = {i["id"]: i for i in issues}

    # Build de-duped intra-P edges: blocker_id → set of blocked_ids
    children: dict[str, set[str]] = {i["id"]: set() for i in issues}
    # Per-issue unique set of intra-P blocker ids (for cascade check + in-degree)
    intra_blockers: dict[str, set[str]] = {i["id"]: set() for i in issues}
    indegree: dict[str, int] = {i["id"]: 0 for i in issues}

    for issue in issues:
        for blocker in issue.get("blockers", []):
            bid = blocker["id"]
            if bid in P:
                if bid not in intra_blockers[issue["id"]]:
                    intra_blockers[issue["id"]].add(bid)
                    indegree[issue["id"]] += 1
                    children[bid].add(issue["id"])

    # Kahn's algorithm: ready = in-degree-0 issues, sorted by (sortOrder, id)
    ready: list[dict[str, Any]] = sorted(
        [i for i in issues if indegree[i["id"]] == 0],
        key=lambda i: (i["sortOrder"], i["id"]),
    )

    order: list[dict[str, Any]] = []
    deferred: list[dict[str, Any]] = []
    deferred_ids: set[str] = set()

    while ready:
        issue = ready.pop(0)
        iid = issue["id"]

        # Cascade: any intra-P blocker already deferred → defer this too
        cascade_blocker = next(
            (by_id[bid] for bid in intra_blockers[iid] if bid in deferred_ids),
            None,
        )
        if cascade_blocker is not None:
            deferred.append({
                "issue": issue,
                "blocker_identifier": cascade_blocker["identifier"],
                "blocker_state_type": cascade_blocker["state"]["type"],
            })
            deferred_ids.add(iid)
        else:
            # External unresolved blocker → defer
            ext_blocker = next(
                (
                    b for b in issue.get("blockers", [])
                    if b["id"] not in P and b["state_type"] not in _RESOLVED_STATE_TYPES
                ),
                None,
            )
            if ext_blocker is not None:
                deferred.append({
                    "issue": issue,
                    "blocker_identifier": ext_blocker["identifier"],
                    "blocker_state_type": ext_blocker["state_type"],
                })
                deferred_ids.add(iid)
            else:
                order.append(issue)

        # Decrement children regardless (deferred nodes still unblock their children
        # in the graph so cycle detection remains accurate)
        for child_id in children[iid]:
            indegree[child_id] -= 1
            if indegree[child_id] == 0:
                child = by_id[child_id]
                # Insert maintaining (sortOrder, id) order
                idx = 0
                key = (child["sortOrder"], child["id"])
                while idx < len(ready) and (ready[idx]["sortOrder"], ready[idx]["id"]) <= key:
                    idx += 1
                ready.insert(idx, child)

    cycle_nodes = [i for i in issues if indegree[i["id"]] > 0]
    if cycle_nodes:
        raise DependencyCycleError([i["identifier"] for i in cycle_nodes])

    return ExecutionPlan(order=order, deferred=deferred)


def _label_name(node: dict[str, Any]) -> str:
    """Render a label node in its prefix form.

    A label in a Linear label *group* arrives as a leaf ``name`` with a
    ``parent`` group; downstream resolvers match on a ``<group>:`` prefix
    (``repo:``, ``model:``), so a grouped label renders as
    ``"<group>:<name>"``. An ungrouped label keeps its bare name, which
    already carries any literal prefix typed into the label name.
    """
    parent = node.get("parent")
    if parent:
        return f"{parent['name']}:{node['name']}"
    return node["name"]


def pending_issues(cycle_id: str) -> ExecutionPlan:
    """Return an ``ExecutionPlan`` for every Todo/Backlog issue in the cycle.

    No pagination: personal cycles fit comfortably in one page. If a cycle
    ever exceeds 100 pending issues, that's a planning problem, not a tool
    problem (see ``PRODUCT_RULES`` Rule A5 — focus is the multiplier).

    Post-processing flattens two wire-shape fields:
    - ``labels { nodes { name parent { name } } }`` → ``labels: list[str]``
      (grouped labels rendered as ``"<group>:<name>"``)
    - ``inverseRelations`` filtered to ``type == "blocks"``
      → ``blockers: list[{id, identifier, state_type}]``; raw key removed.
    """
    data = _post(
        """
        query CyclePending($cycleId: ID!, $stateTypes: [String!]!) {
          issues(
            filter: {
              cycle: { id: { eq: $cycleId } }
              state: { type: { in: $stateTypes } }
            }
            first: 100
          ) {
            nodes {
              id
              identifier
              title
              description
              sortOrder
              state { type name }
              labels { nodes { name parent { name } } }
              inverseRelations { nodes { type issue { id identifier state { type } } } }
            }
          }
        }
        """,
        {"cycleId": cycle_id, "stateTypes": _PENDING_STATE_TYPES},
        operation="pending_issues",
    )
    issues = data["issues"]["nodes"]
    for issue in issues:
        issue["labels"] = [_label_name(node) for node in issue["labels"]["nodes"]]
        issue["blockers"] = [
            {
                "id": node["issue"]["id"],
                "identifier": node["issue"]["identifier"],
                "state_type": node["issue"]["state"]["type"],
            }
            for node in issue["inverseRelations"]["nodes"]
            if node["type"] == "blocks"
        ]
        del issue["inverseRelations"]
    return _plan(issues)


def get_issue(issue_id: str) -> dict[str, Any]:
    """Re-fetch an issue's current state by id."""
    data = _post(
        """
        query Issue($id: String!) {
          issue(id: $id) {
            id
            identifier
            title
            state { type name }
          }
        }
        """,
        {"id": issue_id},
        operation="get_issue",
    )
    issue = data["issue"]
    if issue is None:
        raise RuntimeError(f"Linear issue {issue_id!r} not found")
    return issue


def set_state(issue_id: str, state_name: str) -> None:
    """Transition an issue to the named workflow state.

    Resolves the state ID by name against the configured team and then issues
    an ``issueUpdate`` mutation. No caching — at cycle scale (≤ ~15 issues)
    the extra round-trip is irrelevant and the simpler code is easier to test.
    """
    state_id = _resolve_state_id(state_name)
    data = _post(
        """
        mutation IssueSetState($id: String!, $input: IssueUpdateInput!) {
          issueUpdate(id: $id, input: $input) {
            success
          }
        }
        """,
        {"id": issue_id, "input": {"stateId": state_id}},
        operation="set_state",
    )
    if not data["issueUpdate"]["success"]:
        raise RuntimeError(
            f"Linear issueUpdate failed for {issue_id!r} → {state_name!r}"
        )


def add_comment(issue_id: str, body: str) -> None:
    """Post a comment on a Linear issue."""
    data = _post(
        """
        mutation CommentCreate($input: CommentCreateInput!) {
          commentCreate(input: $input) {
            success
          }
        }
        """,
        {"input": {"issueId": issue_id, "body": body}},
        operation="add_comment",
    )
    if not data["commentCreate"]["success"]:
        raise RuntimeError(f"Linear commentCreate failed for issue {issue_id!r}")


def _resolve_state_id(state_name: str) -> str:
    data = _post(
        """
        query WorkflowState($team: String!, $name: String!) {
          workflowStates(
            filter: {
              team: { name: { eq: $team } }
              name: { eq: $name }
            }
            first: 1
          ) {
            nodes { id }
          }
        }
        """,
        {"team": _TEAM_NAME, "name": state_name},
        operation="resolve_state",
    )
    nodes = data["workflowStates"]["nodes"]
    if not nodes:
        raise RuntimeError(
            f"Linear workflow state {state_name!r} not found for team {_TEAM_NAME!r}"
        )
    return nodes[0]["id"]

"""Handoff artefact a stack-mode worker leaves behind after submitting PRs.

In stack mode the worker drives PR submission itself via the ``pr-finishing``
skill, which runs ``gt``/``gh`` inside the worktree, posts the Linear
review-summary comment, and records the submitted PRs in
``.drain-handoff.json`` as a ``pr_urls`` list. The orchestrator reads that
list back as its confirmation signal — a present, non-empty ``pr_urls`` means
the skill submitted at least one PR; its absence means submission never
completed and the per-repo chain must halt rather than march on.

``read`` never raises: a missing or malformed file returns ``None`` so callers
can treat it as "not submitted yet."
"""
from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path

HANDOFF_FILE = ".drain-handoff.json"


@dataclass(frozen=True)
class PullRequest:
    title: str
    url: str


@dataclass(frozen=True)
class HandoffData:
    pr_urls: tuple[PullRequest, ...]


def write(worktree: Path, data: HandoffData) -> None:
    """Serialise ``data`` to ``<worktree>/.drain-handoff.json``."""
    path = worktree / HANDOFF_FILE
    path.write_text(
        json.dumps(
            {
                "pr_urls": [
                    {"title": pr.title, "url": pr.url} for pr in data.pr_urls
                ],
            },
            indent=2,
        )
    )


def read(worktree: Path) -> HandoffData | None:
    """Return the handoff data for ``worktree``, or ``None`` if absent or invalid.

    A valid handoff has a ``pr_urls`` list with at least one entry, each entry
    a dict carrying string ``title`` and ``url``. An empty list is treated as
    invalid: the skill writes ``pr_urls`` only after a PR is actually created,
    so "present but empty" means no submission happened.
    """
    path = worktree / HANDOFF_FILE
    try:
        payload = json.loads(path.read_text())
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(payload, dict):
        return None
    raw = payload.get("pr_urls")
    if not isinstance(raw, list) or not raw:
        return None
    prs: list[PullRequest] = []
    for entry in raw:
        if not isinstance(entry, dict):
            return None
        title = entry.get("title")
        url = entry.get("url")
        if not isinstance(title, str) or not isinstance(url, str) or not url:
            return None
        prs.append(PullRequest(title=title, url=url))
    return HandoffData(pr_urls=tuple(prs))

"""Per-issue target-repo resolution.

The orchestrator used to be single-repo by construction: every worktree
landed under ``Path.cwd()``. Cycles in this workspace span multiple repos
by design — ``linear-workflow.md`` makes "Affected repos" part of the
six initiative-readiness fields, and the Ops slot deliberately holds
cross-repo maintenance issues — so each issue now carries a
``repo:<name>`` label and ``~/.drain-cycle/repos.yml`` maps the name to
an absolute path on disk.

Two distinct error types so the two halt paths can branch cleanly:

* ``RepoConfigError`` — startup-time problems (missing file, malformed
  YAML, empty, wrong top-level shape). The CLI catches it before any
  Linear traffic, prints to stderr, exits 1, and does **not** write a
  run-log entry — there is no cycle to log against yet.
* ``RepoResolutionError`` — per-issue problems (no ``repo:`` label,
  multiple ``repo:`` labels, name not in config, resolved path missing).
  The orchestrator catches it as a pre-spawn halt: write a run-log
  entry, print the matching ``Halt:`` line, exit 1. No revert is
  attempted because no Linear state was moved yet.
"""
from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any

import yaml

_CONFIG_DISPLAY = "~/.drain-cycle/repos.yml"
_REPO_LABEL_PREFIX = "repo:"

DEFAULT_WORKTREE_CONFIG_PATHS = (".claude", ".mcp.json")
"""Project-scoped config a worker should inherit inside its worktree.

A git worktree checks out only tracked files, so gitignored project config
(`.claude/`, a root `.mcp.json`) is absent unless symlinked in. These two
defaults suit any repo; an operator whose repo uses other tooling (e.g. the
`entire.io` tool's `.entire/`) extends the set via ``worktree_config_paths`` in
``repos.yml``. See :func:`drain_cycle.worktree.link_project_config`."""

_MISSING_CONFIG_HINT = (
    "create it mapping each repo: label to an absolute path, e.g.:\n\n"
    "  repos:\n"
    "    drain-cycle: /Users/you/src/drain-cycle\n"
    "    pde-skills:  /Users/you/src/pde-skills\n\n"
    "see docs/repos.example.yml for a template."
)


class RepoConfigError(RuntimeError):
    """``repos.yml`` is missing or malformed."""


class RepoResolutionError(RuntimeError):
    """An issue cannot be mapped to a target repo."""


def default_config_path() -> Path:
    """Resolved per call so tests can redirect via ``monkeypatch.setenv("HOME", ...)``."""
    return Path.home() / ".drain-cycle" / "repos.yml"


@dataclass(frozen=True)
class Repos:
    """Loaded ``repos.yml`` mapping (``name`` → absolute ``Path``)."""

    mapping: dict[str, Path]
    worktree_config_paths: tuple[str, ...] = DEFAULT_WORKTREE_CONFIG_PATHS
    push_to_main_repos: tuple[str, ...] = ()

    def resolve(self, issue: dict[str, Any]) -> Path:
        labels = [
            label
            for label in issue.get("labels", [])
            if label.startswith(_REPO_LABEL_PREFIX)
        ]
        if not labels:
            raise RepoResolutionError(f"no {_REPO_LABEL_PREFIX} label on issue")
        if len(labels) > 1:
            names = ", ".join(sorted(label.removeprefix(_REPO_LABEL_PREFIX) for label in labels))
            raise RepoResolutionError(f"multiple {_REPO_LABEL_PREFIX} labels: {names}")
        name = labels[0].removeprefix(_REPO_LABEL_PREFIX)
        try:
            path = self.mapping[name]
        except KeyError:
            raise RepoResolutionError(
                f'repo "{name}" not in {_CONFIG_DISPLAY}'
            ) from None
        if not path.exists():
            raise RepoResolutionError(f"resolved path {path} does not exist")
        return path


def _parse_worktree_config_paths(value: Any) -> tuple[str, ...]:
    """Validate the optional ``worktree_config_paths`` key.

    ``None`` (key absent) yields the default. A present value must be a
    non-empty list of relative-path strings — entries are symlinked into a
    worktree, so an absolute path or one containing ``..`` could point outside
    the repo and is rejected. Every failure raises ``RepoConfigError`` naming
    the offending entry.
    """
    if value is None:
        return DEFAULT_WORKTREE_CONFIG_PATHS
    if not isinstance(value, list) or not value:
        raise RepoConfigError(
            f"{_CONFIG_DISPLAY} 'worktree_config_paths' must be a non-empty list"
        )
    entries: list[str] = []
    for entry in value:
        if not isinstance(entry, str) or not entry.strip():
            raise RepoConfigError(
                f"{_CONFIG_DISPLAY} 'worktree_config_paths' entry {entry!r}: "
                "must be a non-empty string"
            )
        if Path(entry).is_absolute():
            raise RepoConfigError(
                f"{_CONFIG_DISPLAY} 'worktree_config_paths' entry {entry!r}: "
                "must be a relative path, not absolute"
            )
        if ".." in Path(entry).parts:
            raise RepoConfigError(
                f"{_CONFIG_DISPLAY} 'worktree_config_paths' entry {entry!r}: "
                "must not contain '..'"
            )
        entries.append(entry)
    return tuple(entries)


def _parse_push_to_main_repos(value: Any) -> tuple[str, ...]:
    """Validate the optional ``push_to_main_repos`` key.

    ``None`` (key absent) yields the default (empty tuple). A present value
    must be a list of repo names matching entries in the ``repos:`` block.
    Every failure raises ``RepoConfigError`` naming the offending entry.
    """
    if value is None:
        return ()
    if not isinstance(value, list):
        raise RepoConfigError(
            f"{_CONFIG_DISPLAY} 'push_to_main_repos' must be a list"
        )
    entries: list[str] = []
    for entry in value:
        if not isinstance(entry, str) or not entry.strip():
            raise RepoConfigError(
                f"{_CONFIG_DISPLAY} 'push_to_main_repos' entry {entry!r}: "
                "must be a non-empty string"
            )
        entries.append(entry)
    return tuple(entries)


def load(path: Path | None = None) -> Repos:
    """Read ``repos.yml`` and return a validated ``Repos``.

    Tilde-prefixed paths inside the file are expanded against ``$HOME``.
    Every failure mode raises ``RepoConfigError`` with a message that
    names the on-disk problem so the operator can fix it without
    re-reading source.
    """
    if path is None:
        path = default_config_path()
    if not path.exists():
        raise RepoConfigError(
            f"{_CONFIG_DISPLAY} not found at {path}\n{_MISSING_CONFIG_HINT}"
        )
    try:
        data = yaml.safe_load(path.read_text())
    except yaml.YAMLError as exc:
        raise RepoConfigError(
            f"{_CONFIG_DISPLAY} is not valid YAML: {exc}"
        ) from None
    if data is None:
        raise RepoConfigError(f"{_CONFIG_DISPLAY} is empty")
    if not isinstance(data, dict) or "repos" not in data:
        raise RepoConfigError(
            f"{_CONFIG_DISPLAY} must have a top-level 'repos:' key"
        )
    block = data["repos"]
    if not isinstance(block, dict) or not block:
        raise RepoConfigError(
            f"{_CONFIG_DISPLAY} 'repos:' must be a non-empty mapping"
        )
    mapping: dict[str, Path] = {}
    for name, value in block.items():
        if not isinstance(value, str):
            raise RepoConfigError(
                f"{_CONFIG_DISPLAY} entry {name!r}: path must be a string"
            )
        mapping[str(name)] = Path(value).expanduser()
    worktree_config_paths = _parse_worktree_config_paths(
        data.get("worktree_config_paths")
    )
    push_to_main_repos = _parse_push_to_main_repos(
        data.get("push_to_main_repos")
    )
    for name in push_to_main_repos:
        if name not in mapping:
            raise RepoConfigError(
                f"{_CONFIG_DISPLAY} 'push_to_main_repos' entry {name!r}: "
                "no such repo in the 'repos:' block"
            )
    return Repos(
        mapping=mapping,
        worktree_config_paths=worktree_config_paths,
        push_to_main_repos=push_to_main_repos,
    )
